import Foundation

/// One section of a consent document, for display as a heading + body block
/// rather than one long unstructured string.
struct ConsentSection: Identifiable {
    let id = UUID()
    let heading: String?
    let body: String
}

/// Full text of the two consent documents patients review and accept during
/// onboarding — content mirrors Nivara_Patient_Informed_Consent.docx and
/// Nivara_Data_Privacy_Consent.docx. The only departures from the source
/// documents are structural: paper signature-line blocks are replaced by
/// this flow's in-app "I agree" acceptance (see OnboardingConsentView), and
/// the two acknowledgement paragraphs are reworded to refer to accepting in
/// the app rather than signing on paper. Legal substance is unchanged — if
/// this pilot's actual process requires a physician countersignature or a
/// different acceptance record, that still needs to be handled outside this
/// demo app.
///
/// Hindi/Telugu/Kannada/Tamil translations were generated by Claude, not a
/// certified legal translator. Numeric/factual terms (fees, the 2-week
/// window, retention period, the 112 emergency number) are preserved
/// exactly across every language — only the surrounding prose was
/// translated. These MUST go through a qualified legal review in each
/// language before being relied on as the actual binding consent text for
/// real patients — this is explicitly flagged, not a substitute for that
/// review.
enum ConsentDocuments {
    static func informedConsentTitle(for language: AppLanguage) -> String {
        informedConsentTitles[language] ?? informedConsentTitles[.english]!
    }

    static func informedConsentSummary(for language: AppLanguage) -> String {
        informedConsentSummaries[language] ?? informedConsentSummaries[.english]!
    }

    static func informedConsentSections(for language: AppLanguage) -> [ConsentSection] {
        informedConsentSectionsByLanguage[language] ?? informedConsentSectionsByLanguage[.english]!
    }

    static func privacyConsentTitle(for language: AppLanguage) -> String {
        privacyConsentTitles[language] ?? privacyConsentTitles[.english]!
    }

    static func privacyConsentSummary(for language: AppLanguage) -> String {
        privacyConsentSummaries[language] ?? privacyConsentSummaries[.english]!
    }

    static func privacyConsentSections(for language: AppLanguage) -> [ConsentSection] {
        privacyConsentSectionsByLanguage[language] ?? privacyConsentSectionsByLanguage[.english]!
    }

    // MARK: - Informed Consent

