            ConsentSection(
                heading: "5. शुल्क",
                body: "इस कार्यक्रम के सभी सेवा शुल्क निवारा हेल्थ को देय और उसके द्वारा एकत्र किए जाते हैं। इसमें मॉनिटरिंग डिवाइस, टेस्ट स्ट्रिप्स, सॉफ्टवेयर और चिकित्सक निगरानी की लागत शामिल है। नामांकन इस प्रकार काम करता है:\n\nडिवाइस जमा राशि। नामांकन के समय आप मॉनिटरिंग किट (ब्लूटूथ ग्लूकोमीटर) के लिए ₹1,500 की वापसी योग्य सुरक्षा जमा राशि प्रदान करते हैं। यह जमा राशि आपको पूरी तरह वापस की जाती है एक बार जब आप डिवाइस को काम करने की स्थिति में वापस कर देते हैं — चाहे आप ट्रायल के दौरान रद्द करें, बाद की तारीख में रद्द करें, या पूरा पायलट पूरा करें। यदि आपके पास पहले से सही डिवाइस है तो यह शुल्क माफ किया जा सकता है।\n\nमासिक शुल्क। नामांकन की लागत ₹1,000/माह है, जो आवर्ती आधार पर बिल की जाती है। इसमें आपकी टेस्ट स्ट्रिप्स शामिल हैं, इसलिए कोई अलग प्रति-स्ट्रिप शुल्क नहीं है। नामांकन के समय, आप हमारे भुगतान प्रदाता के साथ यह आवर्ती भुगतान (एक \"ई-मैंडेट\") सेट करेंगे। आवर्ती डिजिटल भुगतानों के लिए RBI नियमों के अनुरूप, आपको हमेशा प्रत्येक मासिक शुल्क से कम से कम 24 घंटे पहले एक सूचना प्राप्त होगी, और आप उस सूचना के माध्यम से या निवारा टीम से संपर्क करके किसी भी समय उस शुल्क या अपने नामांकन को रद्द कर सकते हैं।\n\nदो-सप्ताह पूर्ण-वापसी विंडो। नामांकन के बाद पहले 2 सप्ताह के लिए, आप किसी भी कारण से रद्द कर सकते हैं और पहले से लिए गए किसी भी मासिक शुल्क की पूर्ण वापसी प्राप्त कर सकते हैं, आपकी डिवाइस जमा राशि के अतिरिक्त, एक बार जब आप डिवाइस को काम करने की स्थिति में वापस कर देते हैं। इस 2-सप्ताह की विंडो के बाद, आप अभी भी धारा 4 (स्वैच्छिक भागीदारी) में वर्णित अनुसार किसी भी समय रद्द कर सकते हैं, लेकिन वर्तमान माह के लिए पहले से लिया गया शुल्क वापसी योग्य नहीं है।"
            ),
            ConsentSection(
                heading: "6. आपका डेटा",
                body: "निवारा इस कार्यक्रम के हिस्से के रूप में आपके स्वास्थ्य डेटा को एकत्र और उपयोग करता है। यह अलग डेटा उपयोग और गोपनीयता सहमति में वर्णित है, जिसे आप इस ऐप में अगली बार समीक्षा और स्वीकार करते हैं।"
            ),
            ConsentSection(
                heading: "7. प्रश्न",
                body: "यदि आपके पास नामांकन से पहले, दौरान, या बाद में इस कार्यक्रम के बारे में कोई प्रश्न है, तो आप WhatsApp के माध्यम से निवारा हेल्थ से संपर्क कर सकते हैं या सीधे अपने उपचार करने वाले चिकित्सक से पूछ सकते हैं।"
            ),
            ConsentSection(
                heading: "स्वीकृति",
                body: "नीचे स्वीकार करके, आप पुष्टि करते हैं कि आपने इस दस्तावेज़ को पढ़ा है (या आपको पढ़कर सुनाया गया है) और समझा है, कि आपके प्रश्नों के उत्तर दिए गए हैं, और कि आप ऊपर वर्णित शर्तों पर स्वेच्छा से निवारा हेल्थ मॉनिटरिंग कार्यक्रम में नामांकन करना चुन रहे हैं।"
            ),
        ],
        .telugu: [
            ConsentSection(
                heading: "1. ఈ ప్రోగ్రామ్ ఏమిటి",
                body: "నివారా హెల్త్, ఇంక్. (\"నివారా\"), బెంగళూరు డయాబెటిస్ సెంటర్‌తో కలిసి, టైప్ 2 డయాబెటిస్ ఉన్న రోగులకు రిమోట్ మానిటరింగ్ సేవను అందిస్తుంది. ఈ సేవలో హోమ్ మానిటరింగ్ కిట్ (బ్లూటూత్-కనెక్ట్ చేయబడిన గ్లూకోమీటర్), స్థాపిత క్లినికల్ మార్గదర్శకాలకు వ్యతిరేకంగా మీ రీడింగ్‌లను సమీక్షించే సాఫ్ట్‌వేర్ ప్లాట్‌ఫారమ్, మరియు మీ చికిత్స చేసే వైద్యుడు ఉన్నారు, వారు వారికి అందిన రీడింగ్‌లను సమీక్షించి మీ సంరక్షణ గురించి ఏదైనా నిర్ణయాలు తీసుకుంటారు.\n\nనివారా ఒక మానిటరింగ్ మరియు కేర్-కోఆర్డినేషన్ సేవ. ఇది ఆసుపత్రి, అత్యవసర సేవ, లేదా మీ చికిత్స చేసే వైద్యునితో మీ కొనసాగుతున్న సంబంధానికి ప్రత్యామ్నాయం కాదు."
            ),
            ConsentSection(
                heading: "2. నివారా ఏమి చేస్తుంది — మరియు ఏమి చేయదు",
                body: "నివారా సాఫ్ట్‌వేర్ (ఏదైనా AI-ఆధారిత విశ్లేషణతో సహా) మీ రోజువారీ రీడింగ్‌లను సమీక్షిస్తుంది మరియు వైద్యుని దృష్టి అవసరమయ్యే నమూనాలను హైలైట్ చేస్తుంది. ఈ పైలట్ సమయంలో, నివారా బృందం కూడా బ్యాకప్ తనిఖీగా రీడింగ్‌లను సమీక్షిస్తుంది మరియు స్వయంచాలకంగా ఫ్లాగ్ చేయబడని ఏదైనా ముఖ్యమైన విషయం గురించి మీ వైద్యునికి విడిగా తెలియజేస్తుంది.\n\nనివారా సాఫ్ట్‌వేర్ స్వయంప్రతిపత్తితో నిర్ధారించదు, మందులను సూచించదు లేదా మార్చదు, లేదా స్పష్టమైన వైద్యుని ఆమోదం లేకుండా ఏ క్లినికల్ నిర్ణయం తీసుకోదు.\n\nమీ చికిత్స గురించి ప్రతి నిర్ణయం — మీ మందులలో ఏదైనా మార్పుతో సహా — భారతదేశంలో ప్రాక్టీస్ చేయడానికి నమోదు చేయబడిన లైసెన్స్ పొందిన వైద్యునిచే తీసుకోబడుతుంది, అది మీ చికిత్స చేసే వైద్యుడు లేదా అధీకృత బ్యాకప్ వైద్యుడు కావచ్చు.\n\nనివారా మీ చికిత్స చేసే వైద్యుడిని లేదా మీ ప్రస్తుత క్లినికల్ సంబంధాన్ని భర్తీ చేయదు. మీరు సాధారణంగా మీ వైద్యుడిని క్రమం తప్పకుండా వ్యక్తిగతంగా లేదా షెడ్యూల్ చేసిన సంరక్షణ కోసం కలవడం కొనసాగించాలి."
            ),
            ConsentSection(
                heading: "3. ప్రతిస్పందన సమయాలు — ఇది అత్యవసర సేవ కాదు",
                body: "మీ రీడింగ్‌లు దృష్టి అవసరమయ్యే నమూనాను చూపించినప్పుడు, సిస్టమ్ వైద్యుని సమీక్ష కోసం అలర్ట్‌ను రూపొందిస్తుంది. సాధారణ సమీక్ష మరియు ప్రతిస్పందన సమయం 24–48 గంటలలో ఉంటుంది, అత్యవసర-థ్రెషోల్డ్ రీడింగ్‌లు (ఉదాహరణకు, చాలా తక్కువ బ్లడ్ షుగర్) మినహా, వీటిని వేగవంతమైన సమీక్ష కోసం ఫ్లాగ్ చేస్తారు.\n\nనివారా యొక్క అలర్ట్ సిస్టమ్ నిజ-సమయంలో వైద్య అత్యవసర పరిస్థితిని గుర్తించడానికి లేదా ప్రతిస్పందించడానికి రూపొందించబడలేదు లేదా ఉద్దేశించబడలేదు. మీరు అత్యవసర పరిస్థితిని అనుభవిస్తుంటే నివారా అలర్ట్ లేదా నివారా బృందం నుండి కాల్ కోసం వేచి ఉండకండి.\n\nఅత్యవసర పరిస్థితిలో: మీరు లేదా కుటుంబ సభ్యుడు ఛాతీ నొప్పి, తీవ్రమైన శ్వాస ఆడకపోవడం, మూర్ఛ, గందరగోళం, స్ట్రోక్ లక్షణాలు, తీవ్రమైన హైపోగ్లైసీమియా, లేదా అత్యవసరంగా అనిపించే ఏదైనా ఇతర లక్షణాన్ని అనుభవిస్తే, వెంటనే 112కి కాల్ చేయండి లేదా సమీప ఆసుపత్రికి వెళ్లండి. నివారా నుండి ప్రతిస్పందన కోసం వేచి ఉండకండి."
            ),
            ConsentSection(
                heading: "4. స్వచ్ఛంద భాగస్వామ్యం",
                body: "ఈ ప్రోగ్రామ్‌లో మీ భాగస్వామ్యం పూర్తిగా స్వచ్ఛందం.\n\nమీరు ఎప్పుడైనా, ఏ కారణం చేతనైనా, కారణం చెప్పకుండా, మరియు మీ వైద్యుడి నుండి మీ కొనసాగుతున్న వైద్య సంరక్షణపై ఎలాంటి ప్రభావం లేకుండా ప్రోగ్రామ్ నుండి వైదొలగవచ్చు.\n\nవైదొలగడానికి, WhatsApp ద్వారా నివారా బృందాన్ని సంప్రదించండి లేదా నేరుగా మీ వైద్యుడికి చెప్పండి."
            ),
            ConsentSection(
                heading: "5. రుసుములు",
                body: "ఈ ప్రోగ్రామ్ కోసం అన్ని సేవా రుసుములు నివారా హెల్త్‌కు చెల్లించదగినవి మరియు దాని ద్వారా వసూలు చేయబడతాయి. ఇందులో మానిటరింగ్ పరికరం, టెస్ట్ స్ట్రిప్‌లు, సాఫ్ట్‌వేర్ మరియు వైద్యుని పర్యవేక్షణ ఖర్చు ఉంటుంది. నమోదు ఈ క్రింది విధంగా పనిచేస్తుంది:\n\nపరికర డిపాజిట్. నమోదు సమయంలో మీరు మానిటరింగ్ కిట్ (బ్లూటూత్ గ్లూకోమీటర్) కోసం ₹1,500 వాపసు చేయదగిన భద్రతా డిపాజిట్‌ను అందిస్తారు. మీరు పరికరాన్ని పనిచేసే స్థితిలో తిరిగి ఇచ్చిన తర్వాత ఈ డిపాజిట్ మీకు పూర్తిగా తిరిగి ఇవ్వబడుతుంది — మీరు ట్రయల్ సమయంలో రద్దు చేసినా, తర్వాత తేదీన రద్దు చేసినా, లేదా పూర్తి పైలట్‌ను పూర్తి చేసినా. మీ వద్ద ఇప్పటికే సరైన పరికరం ఉంటే ఈ రుసుము మాఫీ చేయబడవచ్చు.\n\nమాసిక రుసుము. నమోదుకు నెలకు ₹1,000 ఖర్చవుతుంది, ఇది పునరావృత ప్రాతిపదికన బిల్ చేయబడుతుంది. ఇందులో మీ టెస్ట్ స్ట్రిప్‌లు ఉంటాయి, కాబట్టి ప్రత్యేక ప్రతి-స్ట్రిప్ ఛార్జీ ఉండదు. నమోదు సమయంలో, మీరు మా చెల్లింపు ప్రదాతతో ఈ పునరావృత చెల్లింపు (ఒక \"ఇ-మాండేట్\")ను సెటప్ చేస్తారు. పునరావృత డిజిటల్ చెల్లింపుల కోసం RBI నియమాలకు అనుగుణంగా, మీరు ప్రతి మాసిక ఛార్జీకి కనీసం 24 గంటల ముందు ఎల్లప్పుడూ నోటిఫికేషన్ అందుకుంటారు, మరియు మీరు ఆ నోటిఫికేషన్ ద్వారా లేదా నివారా బృందాన్ని సంప్రదించడం ద్వారా ఎప్పుడైనా ఆ ఛార్జీని లేదా మీ నమోదును రద్దు చేయవచ్చు.\n\nరెండు-వారాల పూర్తి-వాపసు విండో. నమోదు తర్వాత మొదటి 2 వారాలలో, మీరు ఏ కారణం చేతనైనా రద్దు చేయవచ్చు మరియు ఇప్పటికే వసూలు చేసిన ఏదైనా మాసిక రుసుము యొక్క పూర్తి వాపసును, మీ పరికర డిపాజిట్‌తో పాటు, మీరు పరికరాన్ని పనిచేసే స్థితిలో తిరిగి ఇచ్చిన తర్వాత పొందవచ్చు. ఈ 2-వారాల విండో తర్వాత, మీరు ఇప్పటికీ సెక్షన్ 4 (స్వచ్ఛంద భాగస్వామ్యం)లో వివరించిన విధంగా ఎప్పుడైనా రద్దు చేయవచ్చు, కానీ ప్రస్తుత నెలకు ఇప్పటికే వసూలు చేసిన రుసుము వాపసు చేయబడదు."
            ),
            ConsentSection(
                heading: "6. మీ డేటా",
                body: "నివారా ఈ ప్రోగ్రామ్‌లో భాగంగా మీ ఆరోగ్య డేటాను సేకరిస్తుంది మరియు ఉపయోగిస్తుంది. ఇది ప్రత్యేక డేటా వినియోగం & గోప్యతా సమ్మతిలో వివరించబడింది, దీన్ని మీరు ఈ యాప్‌లో తర్వాత సమీక్షించి ఆమోదిస్తారు."
            ),
            ConsentSection(
                heading: "7. ప్రశ్నలు",
                body: "నమోదుకు ముందు, సమయంలో, లేదా తర్వాత ఈ ప్రోగ్రామ్ గురించి మీకు ఏవైనా ప్రశ్నలు ఉంటే, మీరు WhatsApp ద్వారా నివారా హెల్త్‌ను సంప్రదించవచ్చు లేదా నేరుగా మీ చికిత్స చేసే వైద్యుడిని అడగవచ్చు."
            ),
            ConsentSection(
                heading: "అంగీకారం",
                body: "క్రింద అంగీకరించడం ద్వారా, మీరు ఈ పత్రాన్ని చదివారని (లేదా మీకు చదివి వినిపించారని) మరియు అర్థం చేసుకున్నారని, మీ ప్రశ్నలకు సమాధానాలు ఇవ్వబడ్డాయని, మరియు పైన వివరించిన నిబంధనలపై నివారా హెల్త్ మానిటరింగ్ ప్రోగ్రామ్‌లో నమోదు చేసుకోవడానికి మీరు స్వచ్ఛందంగా ఎంచుకుంటున్నారని నిర్ధారిస్తున్నారు."
            ),
        ],
        .kannada: [
            ConsentSection(
                heading: "1. ಈ ಕಾರ್ಯಕ್ರಮ ಏನು",
                body: "ನಿವಾರಾ ಹೆಲ್ತ್, ಇಂಕ್. (\"ನಿವಾರಾ\"), ಬೆಂಗಳೂರು ಡಯಾಬಿಟಿಸ್ ಸೆಂಟರ್‌ನೊಂದಿಗೆ ಸೇರಿ, ಟೈಪ್ 2 ಡಯಾಬಿಟಿಸ್ ಹೊಂದಿರುವ ರೋಗಿಗಳಿಗೆ ದೂರಸ್ಥ ಮೇಲ್ವಿಚಾರಣಾ ಸೇವೆಯನ್ನು ಒದಗಿಸುತ್ತದೆ. ಈ ಸೇವೆಯು ಮನೆ ಮೇಲ್ವಿಚಾರಣಾ ಕಿಟ್ (ಬ್ಲೂಟೂತ್-ಸಂಪರ್ಕಿತ ಗ್ಲೂಕೋಮೀಟರ್), ಸ್ಥಾಪಿತ ಕ್ಲಿನಿಕಲ್ ಮಾರ್ಗಸೂಚಿಗಳ ವಿರುದ್ಧ ನಿಮ್ಮ ವಾಚನಗಳನ್ನು ಪರಿಶೀಲಿಸುವ ಸಾಫ್ಟ್‌ವೇರ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್, ಮತ್ತು ನಿಮ್ಮ ಚಿಕಿತ್ಸಾ ವೈದ್ಯರನ್ನು ಒಳಗೊಂಡಿದೆ, ಅವರು ತಮಗೆ ತಲುಪುವ ವಾಚನಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ನಿಮ್ಮ ಆರೈಕೆಯ ಬಗ್ಗೆ ಯಾವುದೇ ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತಾರೆ.\n\nನಿವಾರಾ ಒಂದು ಮೇಲ್ವಿಚಾರಣೆ ಮತ್ತು ಆರೈಕೆ-ಸಮನ್ವಯ ಸೇವೆಯಾಗಿದೆ. ಇದು ಆಸ್ಪತ್ರೆ, ತುರ್ತು ಸೇವೆ, ಅಥವಾ ನಿಮ್ಮ ಚಿಕಿತ್ಸಾ ವೈದ್ಯರೊಂದಿಗಿನ ನಿಮ್ಮ ನಡೆಯುತ್ತಿರುವ ಸಂಬಂಧಕ್ಕೆ ಪರ್ಯಾಯವಲ್ಲ."
            ),
            ConsentSection(
                heading: "2. ನಿವಾರಾ ಏನು ಮಾಡುತ್ತದೆ — ಮತ್ತು ಏನು ಮಾಡುವುದಿಲ್ಲ",
                body: "ನಿವಾರಾದ ಸಾಫ್ಟ್‌ವೇರ್ (ಯಾವುದೇ AI-ಆಧಾರಿತ ವಿಶ್ಲೇಷಣೆ ಸೇರಿದಂತೆ) ನಿಮ್ಮ ದೈನಂದಿನ ವಾಚನಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ ಮತ್ತು ವೈದ್ಯರ ಗಮನ ಬೇಕಾಗಬಹುದಾದ ಮಾದರಿಗಳನ್ನು ಹೈಲೈಟ್ ಮಾಡುತ್ತದೆ. ಈ ಪೈಲಟ್ ಸಮಯದಲ್ಲಿ, ನಿವಾರಾ ತಂಡವು ಬ್ಯಾಕಪ್ ಪರಿಶೀಲನೆಯಾಗಿ ವಾಚನಗಳನ್ನು ಸಹ ಪರಿಶೀಲಿಸುತ್ತದೆ ಮತ್ತು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಫ್ಲ್ಯಾಗ್ ಆಗದ ಯಾವುದೇ ಮಹತ್ವದ ಸಂಗತಿಯ ಬಗ್ಗೆ ಪ್ರತ್ಯೇಕವಾಗಿ ನಿಮ್ಮ ವೈದ್ಯರಿಗೆ ತಿಳಿಸುತ್ತದೆ.\n\nನಿವಾರಾದ ಸಾಫ್ಟ್‌ವೇರ್ ಸ್ವಾಯತ್ತವಾಗಿ ರೋಗನಿರ್ಣಯ ಮಾಡುವುದಿಲ್ಲ, ಔಷಧಿಯನ್ನು ಸೂಚಿಸುವುದಿಲ್ಲ ಅಥವಾ ಬದಲಾಯಿಸುವುದಿಲ್ಲ, ಅಥವಾ ಸ್ಪಷ್ಟ ವೈದ್ಯರ ಅನುಮೋದನೆಯಿಲ್ಲದೆ ಯಾವುದೇ ಕ್ಲಿನಿಕಲ್ ನಿರ್ಧಾರವನ್ನು ತೆಗೆದುಕೊಳ್ಳುವುದಿಲ್ಲ.\n\nನಿಮ್ಮ ಚಿಕಿತ್ಸೆಯ ಬಗ್ಗೆ ಪ್ರತಿಯೊಂದು ನಿರ್ಧಾರ — ನಿಮ್ಮ ಔಷಧಿಯಲ್ಲಿನ ಯಾವುದೇ ಬದಲಾವಣೆ ಸೇರಿದಂತೆ — ಭಾರತದಲ್ಲಿ ಅಭ್ಯಾಸ ಮಾಡಲು ನೋಂದಾಯಿಸಲಾದ ಪರವಾನಗಿ ಪಡೆದ ವೈದ್ಯರಿಂದ ತೆಗೆದುಕೊಳ್ಳಲ್ಪಡುತ್ತದೆ, ಅದು ನಿಮ್ಮ ಚಿಕಿತ್ಸಾ ವೈದ್ಯರು ಅಥವಾ ಅಧಿಕೃತ ಬ್ಯಾಕಪ್ ವೈದ್ಯರಾಗಿರಬಹುದು.\n\nನಿವಾರಾ ನಿಮ್ಮ ಚಿಕಿತ್ಸಾ ವೈದ್ಯರನ್ನು ಅಥವಾ ನಿಮ್ಮ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಕ್ಲಿನಿಕಲ್ ಸಂಬಂಧವನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ. ನೀವು ಸಾಮಾನ್ಯವಾಗಿ ಮಾಡುವಂತೆ ನಿಯಮಿತ ವೈಯಕ್ತಿಕ ಅಥವಾ ನಿಗದಿತ ಆರೈಕೆಗಾಗಿ ನಿಮ್ಮ ವೈದ್ಯರನ್ನು ನೋಡುವುದನ್ನು ಮುಂದುವರಿಸಬೇಕು."
            ),
            ConsentSection(
                heading: "3. ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯಗಳು — ಇದು ತುರ್ತು ಸೇವೆಯಲ್ಲ",
                body: "ನಿಮ್ಮ ವಾಚನಗಳು ಗಮನ ಬೇಕಾಗಬಹುದಾದ ಮಾದರಿಯನ್ನು ತೋರಿಸಿದಾಗ, ಸಿಸ್ಟಮ್ ವೈದ್ಯರ ಪರಿಶೀಲನೆಗಾಗಿ ಎಚ್ಚರಿಕೆಯನ್ನು ರಚಿಸುತ್ತದೆ. ವಿಶಿಷ್ಟ ಪರಿಶೀಲನೆ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯ 24–48 ಗಂಟೆಗಳ ಒಳಗೆ ಇರುತ್ತದೆ, ತುರ್ತು-ಮಿತಿ ವಾಚನಗಳನ್ನು (ಉದಾಹರಣೆಗೆ, ಅತಿ ಕಡಿಮೆ ರಕ್ತದ ಸಕ್ಕರೆ) ಹೊರತುಪಡಿಸಿ, ಇವುಗಳನ್ನು ವೇಗದ ಪರಿಶೀಲನೆಗಾಗಿ ಫ್ಲ್ಯಾಗ್ ಮಾಡಲಾಗುತ್ತದೆ.\n\nನಿವಾರಾದ ಎಚ್ಚರಿಕೆ ವ್ಯವಸ್ಥೆಯು ನೈಜ ಸಮಯದಲ್ಲಿ ವೈದ್ಯಕೀಯ ತುರ್ತುಸ್ಥಿತಿಯನ್ನು ಪತ್ತೆಹಚ್ಚಲು ಅಥವಾ ಪ್ರತಿಕ್ರಿಯಿಸಲು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿಲ್ಲ ಅಥವಾ ಉದ್ದೇಶಿಸಲಾಗಿಲ್ಲ. ನೀವು ಸಂಭಾವ್ಯ ತುರ್ತುಸ್ಥಿತಿಯನ್ನು ಅನುಭವಿಸುತ್ತಿದ್ದರೆ ನಿವಾರಾ ಎಚ್ಚರಿಕೆ ಅಥವಾ ನಿವಾರಾ ತಂಡದ ಕರೆಗಾಗಿ ಕಾಯಬೇಡಿ.\n\nತುರ್ತುಸ್ಥಿತಿಯಲ್ಲಿ: ನೀವು ಅಥವಾ ಕುಟುಂಬ ಸದಸ್ಯರು ಎದೆ ನೋವು, ತೀವ್ರ ಉಸಿರಾಟದ ತೊಂದರೆ, ಮೂರ್ಛೆ, ಗೊಂದಲ, ಪಾರ್ಶ್ವವಾಯುವಿನ ಲಕ್ಷಣಗಳು, ತೀವ್ರ ಹೈಪೊಗ್ಲೈಸೀಮಿಯಾ, ಅಥವಾ ತುರ್ತುಸ್ಥಿತಿಯಂತೆ ಅನಿಸುವ ಯಾವುದೇ ಇತರ ಲಕ್ಷಣವನ್ನು ಅನುಭವಿಸಿದರೆ, ತಕ್ಷಣ 112 ಗೆ ಕರೆ ಮಾಡಿ ಅಥವಾ ಹತ್ತಿರದ ಆಸ್ಪತ್ರೆಗೆ ಹೋಗಿ. ನಿವಾರಾದಿಂದ ಪ್ರತಿಕ್ರಿಯೆಗಾಗಿ ಕಾಯಬೇಡಿ."
            ),
            ConsentSection(
                heading: "4. ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ",
                body: "ಈ ಕಾರ್ಯಕ್ರಮದಲ್ಲಿ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ.\n\nನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ, ಯಾವುದೇ ಕಾರಣಕ್ಕಾಗಿ, ಕಾರಣ ನೀಡದೆ, ಮತ್ತು ನಿಮ್ಮ ವೈದ್ಯರಿಂದ ನಿಮ್ಮ ನಡೆಯುತ್ತಿರುವ ವೈದ್ಯಕೀಯ ಆರೈಕೆಯ ಮೇಲೆ ಯಾವುದೇ ಪರಿಣಾಮವಿಲ್ಲದೆ ಕಾರ್ಯಕ್ರಮದಿಂದ ಹಿಂದೆ ಸರಿಯಬಹುದು.\n\nಹಿಂದೆ ಸರಿಯಲು, WhatsApp ಮೂಲಕ ನಿವಾರಾ ತಂಡವನ್ನು ಸಂಪರ್ಕಿಸಿ ಅಥವಾ ನೇರವಾಗಿ ನಿಮ್ಮ ವೈದ್ಯರಿಗೆ ತಿಳಿಸಿ."
            ),
            ConsentSection(
                heading: "5. ಶುಲ್ಕಗಳು",
                body: "ಈ ಕಾರ್ಯಕ್ರಮದ ಎಲ್ಲಾ ಸೇವಾ ಶುಲ್ಕಗಳು ನಿವಾರಾ ಹೆಲ್ತ್‌ಗೆ ಪಾವತಿಸಬೇಕಾದ ಮತ್ತು ಅದರಿಂದ ಸಂಗ್ರಹಿಸಲ್ಪಡುತ್ತವೆ. ಇದು ಮೇಲ್ವಿಚಾರಣಾ ಸಾಧನ, ಪರೀಕ್ಷಾ ಸ್ಟ್ರಿಪ್‌ಗಳು, ಸಾಫ್ಟ್‌ವೇರ್ ಮತ್ತು ವೈದ್ಯರ ಮೇಲ್ವಿಚಾರಣೆಯ ವೆಚ್ಚವನ್ನು ಒಳಗೊಂಡಿದೆ. ನೋಂದಣಿ ಈ ಕೆಳಗಿನಂತೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ:\n\nಸಾಧನ ಠೇವಣಿ. ನೋಂದಣಿಯಲ್ಲಿ ನೀವು ಮೇಲ್ವಿಚಾರಣಾ ಕಿಟ್‌ಗಾಗಿ (ಬ್ಲೂಟೂತ್ ಗ್ಲೂಕೋಮೀಟರ್) ₹1,500 ಮರುಪಾವತಿ ಮಾಡಬಹುದಾದ ಭದ್ರತಾ ಠೇವಣಿಯನ್ನು ಒದಗಿಸುತ್ತೀರಿ. ನೀವು ಸಾಧನವನ್ನು ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಸ್ಥಿತಿಯಲ್ಲಿ ಹಿಂತಿರುಗಿಸಿದ ನಂತರ ಈ ಠೇವಣಿಯನ್ನು ನಿಮಗೆ ಪೂರ್ಣವಾಗಿ ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ — ನೀವು ಪ್ರಯೋಗದ ಸಮಯದಲ್ಲಿ ರದ್ದುಗೊಳಿಸಿದರೂ, ನಂತರದ ದಿನಾಂಕದಲ್ಲಿ ರದ್ದುಗೊಳಿಸಿದರೂ, ಅಥವಾ ಪೂರ್ಣ ಪೈಲಟ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸಿದರೂ. ನಿಮ್ಮ ಬಳಿ ಈಗಾಗಲೇ ಸರಿಯಾದ ಸಾಧನ ಇದ್ದರೆ ಈ ಶುಲ್ಕವನ್ನು ಮನ್ನಾ ಮಾಡಬಹುದು.\n\nಮಾಸಿಕ ಶುಲ್ಕ. ನೋಂದಣಿ ತಿಂಗಳಿಗೆ ₹1,000 ವೆಚ್ಚವಾಗುತ್ತದೆ, ಇದನ್ನು ಪುನರಾವರ್ತಿತ ಆಧಾರದ ಮೇಲೆ ಬಿಲ್ ಮಾಡಲಾಗುತ್ತದೆ. ಇದು ನಿಮ್ಮ ಪರೀಕ್ಷಾ ಸ್ಟ್ರಿಪ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ, ಆದ್ದರಿಂದ ಪ್ರತ್ಯೇಕ ಪ್ರತಿ-ಸ್ಟ್ರಿಪ್ ಶುಲ್ಕವಿಲ್ಲ. ನೋಂದಣಿಯಲ್ಲಿ, ನೀವು ನಮ್ಮ ಪಾವತಿ ಪೂರೈಕೆದಾರರೊಂದಿಗೆ ಈ ಪುನರಾವರ್ತಿತ ಪಾವತಿಯನ್ನು (ಒಂದು \"ಇ-ಮ್ಯಾಂಡೇಟ್\") ಸ್ಥಾಪಿಸುತ್ತೀರಿ. ಪುನರಾವರ್ತಿತ ಡಿಜಿಟಲ್ ಪಾವತಿಗಳಿಗಾಗಿ RBI ನಿಯಮಗಳಿಗೆ ಅನುಗುಣವಾಗಿ, ಪ್ರತಿ ಮಾಸಿಕ ಶುಲ್ಕಕ್ಕೂ ಕನಿಷ್ಠ 24 ಗಂಟೆಗಳ ಮೊದಲು ನಿಮಗೆ ಯಾವಾಗಲೂ ಅಧಿಸೂಚನೆ ಸಿಗುತ್ತದೆ, ಮತ್ತು ಆ ಅಧಿಸೂಚನೆಯ ಮೂಲಕ ಅಥವಾ ನಿವಾರಾ ತಂಡವನ್ನು ಸಂಪರ್ಕಿಸುವ ಮೂಲಕ ನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಆ ಶುಲ್ಕ ಅಥವಾ ನಿಮ್ಮ ನೋಂದಣಿಯನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದು.\n\nಎರಡು-ವಾರದ ಪೂರ್ಣ-ಮರುಪಾವತಿ ವಿಂಡೋ. ನೋಂದಣಿಯ ನಂತರ ಮೊದಲ 2 ವಾರಗಳಲ್ಲಿ, ನೀವು ಯಾವುದೇ ಕಾರಣಕ್ಕಾಗಿ ರದ್ದುಗೊಳಿಸಬಹುದು ಮತ್ತು ಈಗಾಗಲೇ ವಿಧಿಸಲಾದ ಯಾವುದೇ ಮಾಸಿಕ ಶುಲ್ಕದ ಪೂರ್ಣ ಮರುಪಾವತಿಯನ್ನು, ನಿಮ್ಮ ಸಾಧನ ಠೇವಣಿಯ ಜೊತೆಗೆ, ನೀವು ಸಾಧನವನ್ನು ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಸ್ಥಿತಿಯಲ್ಲಿ ಹಿಂತಿರುಗಿಸಿದ ನಂತರ ಪಡೆಯಬಹುದು. ಈ 2-ವಾರದ ವಿಂಡೋದ ನಂತರ, ನೀವು ಇನ್ನೂ ವಿಭಾಗ 4 ರಲ್ಲಿ (ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ) ವಿವರಿಸಿದಂತೆ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ರದ್ದುಗೊಳಿಸಬಹುದು, ಆದರೆ ಪ್ರಸ್ತುತ ತಿಂಗಳಿಗೆ ಈಗಾಗಲೇ ವಿಧಿಸಲಾದ ಶುಲ್ಕವನ್ನು ಮರುಪಾವತಿ ಮಾಡಲಾಗುವುದಿಲ್ಲ."
            ),
            ConsentSection(
                heading: "6. ನಿಮ್ಮ ಡೇಟಾ",
                body: "ನಿವಾರಾ ಈ ಕಾರ್ಯಕ್ರಮದ ಭಾಗವಾಗಿ ನಿಮ್ಮ ಆರೋಗ್ಯ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ ಮತ್ತು ಬಳಸುತ್ತದೆ. ಇದನ್ನು ಪ್ರತ್ಯೇಕ ಡೇಟಾ ಬಳಕೆ ಮತ್ತು ಗೌಪ್ಯತಾ ಒಪ್ಪಿಗೆಯಲ್ಲಿ ವಿವರಿಸಲಾಗಿದೆ, ಅದನ್ನು ನೀವು ಈ ಆ್ಯಪ್‌ನಲ್ಲಿ ಮುಂದೆ ಪರಿಶೀಲಿಸಿ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತೀರಿ."
            ),
            ConsentSection(
                heading: "7. ಪ್ರಶ್ನೆಗಳು",
                body: "ನೋಂದಣಿಗೆ ಮೊದಲು, ಸಮಯದಲ್ಲಿ, ಅಥವಾ ನಂತರ ಈ ಕಾರ್ಯಕ್ರಮದ ಬಗ್ಗೆ ನಿಮಗೆ ಯಾವುದೇ ಪ್ರಶ್ನೆಗಳಿದ್ದರೆ, ನೀವು WhatsApp ಮೂಲಕ ನಿವಾರಾ ಹೆಲ್ತ್ ಅನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು ಅಥವಾ ನೇರವಾಗಿ ನಿಮ್ಮ ಚಿಕಿತ್ಸಾ ವೈದ್ಯರನ್ನು ಕೇಳಬಹುದು."
            ),
            ConsentSection(
                heading: "ಅಂಗೀಕಾರ",
                body: "ಕೆಳಗೆ ಒಪ್ಪಿಕೊಳ್ಳುವ ಮೂಲಕ, ನೀವು ಈ ದಾಖಲೆಯನ್ನು ಓದಿದ್ದೀರಿ (ಅಥವಾ ನಿಮಗೆ ಓದಿ ಹೇಳಲಾಗಿದೆ) ಮತ್ತು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೀರಿ, ನಿಮ್ಮ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಲಾಗಿದೆ, ಮತ್ತು ಮೇಲೆ ವಿವರಿಸಿದ ನಿಯಮಗಳ ಮೇಲೆ ನಿವಾರಾ ಹೆಲ್ತ್ ಮೇಲ್ವಿಚಾರಣಾ ಕಾರ್ಯಕ್ರಮದಲ್ಲಿ ನೋಂದಾಯಿಸಿಕೊಳ್ಳಲು ನೀವು ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿ ಆಯ್ಕೆ ಮಾಡುತ್ತಿದ್ದೀರಿ ಎಂದು ದೃಢೀಕರಿಸುತ್ತೀರಿ."
            ),
        ],
        .tamil: [
            ConsentSection(
                heading: "1. இந்த திட்டம் என்ன",
                body: "நிவாரா ஹெல்த், இன்க். (\"நிவாரா\"), பெங்களூரு டயாபடீஸ் சென்டருடன் இணைந்து, டைப் 2 நீரிழிவு நோயாளிகளுக்கு தொலைதூர கண்காணிப்பு சேவையை வழங்குகிறது. இந்த சேவையில் வீட்டு கண்காணிப்பு கிட் (புளூடூத்-இணைக்கப்பட்ட குளுக்கோமீட்டர்), நிறுவப்பட்ட மருத்துவ வழிகாட்டுதல்களுக்கு எதிராக உங்கள் அளவீடுகளை மதிப்பாய்வு செய்யும் மென்பொருள் தளம், மற்றும் உங்கள் சிகிச்சை மருத்துவர் ஆகியோர் அடங்குவர், அவர்கள் தங்களுக்கு வரும் அளவீடுகளை மதிப்பாய்வு செய்து உங்கள் பராமரிப்பு குறித்த எந்த முடிவுகளையும் எடுக்கிறார்கள்.\n\nநிவாரா ஒரு கண்காணிப்பு மற்றும் பராமரிப்பு-ஒருங்கிணைப்பு சேவை ஆகும். இது மருத்துவமனை, அவசரகால சேவை, அல்லது உங்கள் சிகிச்சை மருத்துவருடனான உங்கள் தொடர்ச்சியான உறவுக்கு மாற்று அல்ல."
            ),
            ConsentSection(
                heading: "2. நிவாரா என்ன செய்கிறது — மற்றும் என்ன செய்யாது",
                body: "நிவாராவின் மென்பொருள் (எந்த AI-அடிப்படையிலான பகுப்பாய்வு உட்பட) உங்கள் தினசரி அளவீடுகளை மதிப்பாய்வு செய்து, மருத்துவரின் கவனம் தேவைப்படக்கூடிய வடிவங்களை முன்னிலைப்படுத்துகிறது. இந்த பைலட்டின் போது, நிவாரா குழுவும் காப்பு சோதனையாக அளவீடுகளை மதிப்பாய்வு செய்து, தானாக கொடியிடப்படாத ஏதேனும் முக்கியமான விஷயத்தை தனித்தனியாக உங்கள் மருத்துவருக்குத் தெரிவிக்கிறது.\n\nநிவாராவின் மென்பொருள் தன்னாட்சியாக நோயறிதல் செய்யாது, மருந்து பரிந்துரைக்காது அல்லது மாற்றாது, அல்லது தெளிவான மருத்துவர் ஒப்புதல் இல்லாமல் எந்த மருத்துவ முடிவையும் எடுக்காது.\n\nஉங்கள் சிகிச்சை குறித்த ஒவ்வொரு முடிவும் — உங்கள் மருந்தில் ஏதேனும் மாற்றம் உட்பட — இந்தியாவில் பயிற்சி செய்ய பதிவுசெய்யப்பட்ட உரிமம் பெற்ற மருத்துவரால் எடுக்கப்படுகிறது, அது உங்கள் சிகிச்சை மருத்துவர் அல்லது அங்கீகரிக்கப்பட்ட காப்பு மருத்துவராக இருக்கலாம்.\n\nநிவாரா உங்கள் சிகிச்சை மருத்துவரையோ உங்கள் தற்போதைய மருத்துவ உறவையோ மாற்றாது. நீங்கள் வழக்கம் போல் உங்கள் மருத்துவரை தொடர்ந்து சந்தித்து வழக்கமான நேரடி அல்லது திட்டமிடப்பட்ட பராமரிப்பைப் பெற வேண்டும்."
            ),
            ConsentSection(
                heading: "3. பதில் நேரங்கள் — இது அவசரகால சேவை அல்ல",
                body: "உங்கள் அளவீடுகள் கவனம் தேவைப்படக்கூடிய ஒரு வடிவத்தைக் காட்டும்போது, கணினி மருத்துவர் மதிப்பாய்வுக்காக ஒரு எச்சரிக்கையை உருவாக்குகிறது. வழக்கமான மதிப்பாய்வு மற்றும் பதில் நேரம் 24–48 மணி நேரத்திற்குள் உள்ளது, அவசர-வரம்பு அளவீடுகளைத் தவிர (உதாரணமாக, மிகக் குறைவான இரத்த சர்க்கரை), இவை விரைவான மதிப்பாய்வுக்காக கொடியிடப்படும்.\n\nநிவாராவின் எச்சரிக்கை அமைப்பு நிகழ்நேரத்தில் மருத்துவ அவசரநிலையைக் கண்டறிய அல்லது பதிலளிக்க வடிவமைக்கப்படவில்லை அல்லது நோக்கமாகக் கொள்ளப்படவில்லை. நீங்கள் சாத்தியமான அவசரநிலையை அனுபவித்தால் நிவாரா எச்சரிக்கை அல்லது நிவாரா குழுவின் அழைப்புக்காக காத்திருக்க வேண்டாம்.\n\nஅவசரநிலையில்: நீங்கள் அல்லது ஒரு குடும்ப உறுப்பினர் மார்பு வலி, கடுமையான மூச்சுத் திணறல், மயக்கம், குழப்பம், பக்கவாத அறிகுறிகள், கடுமையான ஹைப்போகிளைசீமியா, அல்லது அவசரநிலை போல் உணரும் வேறு எந்த அறிகுறியையும் அனுபவித்தால், உடனடியாக 112 ஐ அழைக்கவும் அல்லது அருகிலுள்ள மருத்துவமனைக்குச் செல்லவும். நிவாராவிடமிருந்து பதிலுக்காக காத்திருக்க வேண்டாம்."
            ),
            ConsentSection(
                heading: "4. தன்னார்வ பங்கேற்பு",
                body: "இந்த திட்டத்தில் உங்கள் பங்கேற்பு முற்றிலும் தன்னார்வமானது.\n\nநீங்கள் எந்த நேரத்திலும், எந்த காரணத்திற்காகவும், காரணம் தெரிவிக்காமல், உங்கள் மருத்துவரிடமிருந்து உங்கள் தொடர்ச்சியான மருத்துவ பராமரிப்பில் எந்த தாக்கமும் இல்லாமல் திட்டத்திலிருந்து விலகலாம்.\n\nவிலக, WhatsApp மூலம் நிவாரா குழுவைத் தொடர்பு கொள்ளவும் அல்லது நேரடியாக உங்கள் மருத்துவரிடம் தெரிவிக்கவும்."
            ),
            ConsentSection(
                heading: "5. கட்டணங்கள்",
                body: "இந்த திட்டத்திற்கான அனைத்து சேவைக் கட்டணங்களும் நிவாரா ஹெல்த்திற்கு செலுத்தப்பட வேண்டியவை மற்றும் அதனால் வசூலிக்கப்படுகின்றன. இதில் கண்காணிப்பு சாதனம், சோதனை ஸ்ட்ரிப்புகள், மென்பொருள் மற்றும் மருத்துவர் மேற்பார்வையின் செலவு அடங்கும். பதிவு பின்வருமாறு செயல்படுகிறது:\n\nசாதன டெபாசிட். பதிவின் போது நீங்கள் கண்காணிப்பு கிட்டிற்காக (புளூடூத் குளுக்கோமீட்டர்) ₹1,500 திரும்பப்பெறக்கூடிய பாதுகாப்பு டெபாசிட்டை வழங்குகிறீர்கள். நீங்கள் சாதனத்தை வேலை செய்யும் நிலையில் திருப்பிக் கொடுத்தவுடன் இந்த டெபாசிட் உங்களுக்கு முழுமையாகத் திருப்பித் தரப்படும் — நீங்கள் சோதனையின் போது ரத்து செய்தாலும், பிற்பகுதியில் ரத்து செய்தாலும், அல்லது முழு பைலட்டையும் முடித்தாலும். உங்களிடம் ஏற்கனவே சரியான சாதனம் இருந்தால் இந்தக் கட்டணம் தள்ளுபடி செய்யப்படலாம்.\n\nமாதாந்திர கட்டணம். பதிவு மாதத்திற்கு ₹1,000 செலவாகும், இது தொடர் அடிப்படையில் பில் செய்யப்படும். இதில் உங்கள் சோதனை ஸ்ட்ரிப்புகள் அடங்கும், எனவே தனி ஸ்ட்ரிப் கட்டணம் இல்லை. பதிவின் போது, எங்கள் பணம் செலுத்தும் வழங்குநருடன் இந்த தொடர் கட்டணத்தை (ஒரு \"இ-மேன்டேட்\") நீங்கள் அமைப்பீர்கள். தொடர் டிஜிட்டல் கட்டணங்களுக்கான RBI விதிகளுக்கு இணங்க, ஒவ்வொரு மாதாந்திர கட்டணத்திற்கும் குறைந்தது 24 மணி நேரத்திற்கு முன் உங்களுக்கு எப்போதும் அறிவிப்பு கிடைக்கும், மேலும் அந்த அறிவிப்பு மூலமாகவோ அல்லது நிவாரா குழுவைத் தொடர்பு கொள்வதன் மூலமாகவோ எந்த நேரத்திலும் அந்த கட்டணத்தையோ உங்கள் பதிவையோ ரத்து செய்யலாம்.\n\nஇரண்டு-வார முழு-திருப்பிச் செலுத்தல் காலம். பதிவுக்குப் பிறகு முதல் 2 வாரங்களுக்கு, நீங்கள் எந்த காரணத்திற்காகவும் ரத்து செய்யலாம் மற்றும் ஏற்கனவே வசூலிக்கப்பட்ட எந்த மாதாந்திர கட்டணத்தையும், உங்கள் சாதன டெபாசிட்டுடன் சேர்த்து, நீங்கள் சாதனத்தை வேலை செய்யும் நிலையில் திருப்பிக் கொடுத்தவுடன் முழுமையாகத் திரும்பப் பெறலாம். இந்த 2-வார காலத்திற்குப் பிறகு, நீங்கள் இன்னும் பிரிவு 4 இல் (தன்னார்வ பங்கேற்பு) விவரிக்கப்பட்டுள்ளபடி எந்த நேரத்திலும் ரத்து செய்யலாம், ஆனால் தற்போதைய மாதத்திற்கு ஏற்கனவே வசூலிக்கப்பட்ட கட்டணம் திரும்பப் பெற முடியாது."
            ),
            ConsentSection(
                heading: "6. உங்கள் தரவு",
                body: "நிவாரா இந்த திட்டத்தின் ஒரு பகுதியாக உங்கள் உடல்நல தரவை சேகரித்து பயன்படுத்துகிறது. இது தனி தரவு பயன்பாடு & தனியுரிமை ஒப்புதலில் விவரிக்கப்பட்டுள்ளது, இதை நீங்கள் இந்த ஆப்பில் அடுத்ததாக மதிப்பாய்வு செய்து ஏற்றுக்கொள்கிறீர்கள்."
            ),
            ConsentSection(
                heading: "7. கேள்விகள்",
                body: "பதிவுக்கு முன், போது, அல்லது பின் இந்த திட்டத்தைப் பற்றி உங்களுக்கு ஏதேனும் கேள்விகள் இருந்தால், நீங்கள் WhatsApp மூலம் நிவாரா ஹெல்த்தைத் தொடர்பு கொள்ளலாம் அல்லது நேரடியாக உங்கள் சிகிச்சை மருத்துவரிடம் கேட்கலாம்."
            ),
            ConsentSection(
                heading: "ஒப்புதல்",
                body: "கீழே ஏற்றுக்கொள்வதன் மூலம், நீங்கள் இந்த ஆவணத்தைப் படித்து (அல்லது உங்களுக்குப் படித்துக் காட்டப்பட்டு) புரிந்துகொண்டீர்கள் என்றும், உங்கள் கேள்விகளுக்கு பதிலளிக்கப்பட்டுள்ளது என்றும், மேலே விவரிக்கப்பட்டுள்ள நிபந்தனைகளின் அடிப்படையில் நிவாரா ஹெல்த் கண்காணிப்பு திட்டத்தில் பதிவு செய்ய நீங்கள் தன்னார்வமாக தேர்வு செய்கிறீர்கள் என்றும் உறுதிப்படுத்துகிறீர்கள்."
            ),
        ],
    ]

