    private static let privacyConsentTitles: [AppLanguage: String] = [
        .english: "Data Use & Privacy Consent",
        .hindi: "डेटा उपयोग और गोपनीयता सहमति",
        .telugu: "డేటా వినియోగం & గోప్యతా సమ్మతి",
        .kannada: "ಡೇಟಾ ಬಳಕೆ ಮತ್ತು ಗೌಪ್ಯತಾ ಒಪ್ಪಿಗೆ",
